META = dict(nama="Industrial Manufacturing", jp="工業製品製造業", emoji="⚙️", co="製造工場")
SPEC = dict(kerja="安全と品質をとても大切にして製品を作っている", kerja_id="membuat produk dengan sangat mengutamakan keselamatan dan kualitas", soal={
 "shibou-01": ("なぜ工業製品製造の仕事を選びましたか。", "Mengapa Anda memilih pekerjaan manufaktur industri?", "小さいころから、機械や物を作ることが好きでした。自分が作った製品が使われるのが楽しみです。", "Sejak kecil saya suka mesin dan membuat sesuatu. Saya senang membayangkan produk buatan saya dipakai orang.", [("製造", "manufaktur"), ("機械", "mesin"), ("製品", "produk"), ("作る", "membuat")]),
 "shibou-02": ("なぜ日本で製造の仕事を学びたいですか。", "Mengapa Anda ingin belajar manufaktur di Jepang?", "日本の工場は、品質管理や安全管理がとても進んでいると聞きました。その方法を学びたいです。", "Saya dengar pabrik Jepang sangat maju dalam pengendalian kualitas dan keselamatan. Saya ingin mempelajari metodenya.", [("品質管理", "pengendalian kualitas"), ("安全管理", "manajemen keselamatan"), ("学ぶ", "belajar")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "部品から製品ができあがるのを見るのが好きです。正確に作る仕事に、やりがいを感じます。", "Saya suka melihat suku cadang menjadi produk jadi. Saya merasa pekerjaan membuat dengan akurat itu bermakna.", [("部品", "suku cadang"), ("正確", "akurat"), ("やりがい", "rasa bermakna")]),
 "shibou-05": ("製造の仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan manufaktur?", "新しい機械の使い方を覚えて、できる仕事が増えることです。日本の技術も学びたいです。", "Mempelajari cara memakai mesin baru sehingga pekerjaan yang bisa saya lakukan bertambah. Saya juga ingin belajar teknologi Jepang.", [("使い方", "cara pakai"), ("覚える", "menghafal/menguasai"), ("技術", "teknologi")]),
 "shigoto-01": ("工業製品製造の主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama manufaktur industri?", "機械を使って、金属や部品を加工したり、組み立てたりする仕事だと思います。完成した製品の検査もあります。", "Saya kira pekerjaannya memproses logam dan suku cadang dengan mesin, merakitnya, dan juga memeriksa produk jadi.", [("加工", "pemrosesan"), ("組み立て", "perakitan"), ("検査", "inspeksi")]),
 "shigoto-02": ("朝早くから、または交替で働くことはできますか。", "Bisakah Anda bekerja dari pagi buta atau bergantian shift?", "はい、できます。生活のリズムを作って、体調に気をつけます。", "Ya, bisa. Saya akan membuat ritme hidup yang teratur dan menjaga kondisi badan.", [("交替勤務", "kerja shift"), ("リズム", "ritme"), ("体調", "kondisi badan")]),
 "shigoto-03": ("工場の中で、一日中立って働けますか。", "Bisakah Anda berdiri bekerja seharian di dalam pabrik?", "はい、大丈夫です。立つ仕事に慣れています。休み時間には、足を休めます。", "Ya, tidak masalah. Saya terbiasa berdiri saat kerja. Saat istirahat saya mengistirahatkan kaki.", [("立つ", "berdiri"), ("慣れる", "terbiasa"), ("休み時間", "waktu istirahat")]),
 "shigoto-04": ("同じ作業を、毎日くり返す仕事ですが、大丈夫ですか。", "Pekerjaan ini mengulang tugas yang sama setiap hari, apakah Anda baik-baik saja?", "はい、大丈夫です。同じ作業でも、毎回、集中してていねいにやります。", "Ya, tidak masalah. Walau tugasnya sama, setiap kali saya fokus dan mengerjakannya dengan teliti.", [("くり返す", "mengulang"), ("集中", "konsentrasi"), ("ていねい", "teliti")]),
 "shigoto-05": ("機械の音や、油のにおいがある環境でも大丈夫ですか。", "Apakah Anda baik-baik saja dengan suara mesin dan bau oli?", "はい、大丈夫です。必要なときは、耳せんやマスクをつけます。", "Ya, tidak masalah. Bila perlu saya memakai penyumbat telinga dan masker.", [("音", "suara"), ("油", "oli"), ("耳せん", "penyumbat telinga")]),
 "shigoto-06": ("注文が多い時期に、残業があっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan lembur saat pesanan banyak?", "はい、大丈夫です。忙しい時期は、チームで協力してがんばります。体調にも気をつけます。", "Ya, tidak masalah. Saat sibuk kami bekerja sama dan berusaha. Saya juga menjaga kondisi badan.", [("注文", "pesanan"), ("残業", "lembur"), ("協力", "kerja sama")]),
 "shigoto-07": ("機械を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai mesin?", "使う前に、機械の状態を確認します。動いている部分には、手を入れません。使い方が分からないときは、使いません。", "Sebelum dipakai saya memeriksa kondisi mesin. Saya tidak memasukkan tangan ke bagian yang bergerak. Kalau tidak tahu cara pakainya, saya tidak memakainya.", [("機械", "mesin"), ("確認", "memastikan"), ("手を入れる", "memasukkan tangan")]),
 "shigoto-08": ("熱や火花が出る作業でも大丈夫ですか。", "Apakah Anda baik-baik saja dengan pekerjaan yang menghasilkan panas dan percikan api?", "はい、大丈夫です。保護めがねや手袋をつけて、先輩の方法を守って作業します。", "Ya, tidak masalah. Saya memakai kacamata pelindung dan sarung tangan serta mengikuti cara senior.", [("火花", "percikan api"), ("保護めがね", "kacamata pelindung"), ("熱", "panas")]),
 "shigoto-09": ("製品を作る仕事で、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting dalam pekerjaan membuat produk?", "決められた寸法や手順を守ることだと思います。ミスがあったら、すぐに報告します。", "Menurut saya, mematuhi ukuran dan prosedur yang ditentukan. Kalau ada kesalahan saya segera melapor.", [("寸法", "ukuran"), ("手順", "prosedur"), ("品質", "kualitas")]),
 "shigoto-10": ("図面や、作業指示書を見ることはできますか。", "Apakah Anda bisa membaca gambar kerja dan lembar instruksi kerja?", "まだ難しいところもありますが、勉強しています。分からないところは、先輩に聞きます。", "Masih ada bagian yang sulit, tetapi saya sedang belajar. Bagian yang tidak paham saya tanyakan kepada senior.", [("図面", "gambar kerja"), ("指示書", "lembar instruksi"), ("勉強する", "belajar")]),
 "shigoto-11": ("品質に問題がある製品を見つけたら、どうしますか。", "Apa yang Anda lakukan kalau menemukan produk bermasalah?", "勝手に直したり、捨てたりしないで、すぐに責任者に報告します。", "Saya tidak memperbaiki atau membuangnya sembarangan, tetapi segera melapor kepada penanggung jawab.", [("不良品", "produk cacat"), ("報告", "melapor"), ("責任者", "penanggung jawab")]),
 "shigoto-12": ("5Sという言葉を知っていますか。", "Apakah Anda tahu istilah 5S?", "整理、整頓、清掃、清潔、しつけのことだと聞きました。きれいで安全な職場のための大切な決まりだと思います。", "Saya dengar itu seiri, seiton, seisō, seiketsu, dan shitsuke. Saya kira itu aturan penting untuk tempat kerja yang bersih dan aman.", [("整理整頓", "rapi dan tertata"), ("清掃", "pembersihan"), ("職場", "tempat kerja")]),
 "shigoto-13": ("測定する道具を使ったことはありますか。", "Apakah Anda pernah memakai alat ukur?", "ノギスや定規を少し使ったことがあります。正しい使い方を、これから勉強します。", "Saya pernah sedikit memakai jangka sorong dan penggaris. Saya akan mempelajari cara pakai yang benar.", [("ノギス", "jangka sorong"), ("測る", "mengukur"), ("正確", "akurat")]),
 "taiou-02": ("製品を間違えて作ってしまったら、どうしますか。", "Apa yang Anda lakukan kalau keliru membuat produk?", "すぐに正直に報告します。どうして間違えたか考えて、次は確認を一回多くします。", "Saya segera melapor jujur. Saya memikirkan penyebab kesalahannya dan lain kali menambah satu kali pengecekan.", [("間違える", "keliru"), ("報告", "melapor"), ("確認", "pengecekan")]),
 "taiou-06": ("急に、作業の予定が変わったら、どうしますか。", "Apa yang Anda lakukan kalau rencana kerja berubah mendadak?", "責任者の指示をよく聞いて、新しい作業を始めます。分からないときは、すぐに聞きます。", "Saya mendengarkan instruksi penanggung jawab dan memulai pekerjaan baru. Kalau tidak paham, saya langsung bertanya.", [("急に", "mendadak"), ("指示", "instruksi"), ("予定", "rencana")]),
 "taiou-08": ("機械が急に止まったら、どうしますか。", "Apa yang Anda lakukan kalau mesin mendadak berhenti?", "自分で直さないで、すぐに電源を切って、責任者に知らせます。", "Saya tidak memperbaikinya sendiri, segera mematikan daya dan memberi tahu penanggung jawab.", [("止まる", "berhenti"), ("電源", "daya listrik"), ("知らせる", "memberi tahu")]),
 "taiou-11": ("忙しい時期で、疲れているとき、どう気持ちを保ちますか。", "Bagaimana Anda menjaga semangat saat sibuk dan lelah?", "忙しい時期は短いと理解しています。しっかり寝て、食事をとって、体調を保ちます。", "Saya paham musim sibuk itu singkat. Saya tidur cukup, makan baik, dan menjaga kondisi badan.", [("疲れる", "lelah"), ("体調", "kondisi badan"), ("睡眠", "tidur")]),
 "taiou-12": ("先輩の説明が専門用語ばかりで、分からないとき、どうしますか。", "Apa yang Anda lakukan kalau penjelasan senior penuh istilah teknis yang tidak Anda pahami?", "「すみません、この言葉の意味を教えてください」と聞きます。メモして、あとで復習します。", "Saya bertanya \"Maaf, tolong jelaskan arti kata ini\". Saya mencatatnya dan mengulang pelajarannya nanti.", [("専門用語", "istilah teknis"), ("意味", "arti"), ("復習", "mengulang pelajaran")]),
 "tim-01": ("ラインで、チームの人と、どのように作業を分けますか。", "Di lini produksi, bagaimana Anda membagi kerja dengan tim?", "責任者の指示で、担当の工程が決まります。早く終わったら、遅れている人を手伝います。", "Sesuai instruksi penanggung jawab, proses yang menjadi tugas saya ditentukan. Kalau selesai lebih dulu, saya membantu yang tertinggal.", [("工程", "proses"), ("担当", "penanggung jawab tugas"), ("手伝う", "membantu")]),
 "tim-02": ("前の工程の人にミスがあったとき、どうしますか。", "Apa yang Anda lakukan kalau ada kesalahan dari proses sebelumnya?", "責めないで、すぐに責任者に知らせます。次の人が困らないように、確認します。", "Saya tidak menyalahkan, tetapi segera memberi tahu penanggung jawab. Saya memeriksa agar orang berikutnya tidak kesulitan.", [("工程", "proses"), ("知らせる", "memberi tahu"), ("確認", "memastikan")]),
 "tim-03": ("交替の時、次の人に、どのように引き継ぎますか。", "Bagaimana Anda serah terima kepada orang shift berikutnya?", "機械の様子と、作業の進み具合を、はっきり伝えます。メモも残します。", "Saya menyampaikan kondisi mesin dan kemajuan pekerjaan dengan jelas. Saya juga meninggalkan catatan.", [("引き継ぎ", "serah terima"), ("進み具合", "kemajuan"), ("メモ", "catatan")]),
 "tim-04": ("工場の仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan rekan di pabrik?", "毎日、元気にあいさつをします。教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diajari, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("仲間", "rekan"), ("仲良くなる", "menjadi akrab")]),
 "anzen-01": ("工場に入るとき、必ず身につけるものは何ですか。", "Apa yang wajib dikenakan saat memasuki pabrik?", "ヘルメットや帽子、作業服、安全靴を必ず着けます。必要なときは、保護めがねや手袋も使います。", "Saya wajib memakai helm atau topi, pakaian kerja, dan sepatu keselamatan. Bila perlu saya juga memakai kacamata pelindung dan sarung tangan.", [("安全靴", "sepatu keselamatan"), ("保護めがね", "kacamata pelindung"), ("作業服", "pakaian kerja")]),
 "anzen-02": ("機械を掃除したり、直したりするとき、何をしますか。", "Apa yang Anda lakukan saat membersihkan atau memperbaiki mesin?", "必ず機械を止めて、電源を切ります。「作業中」の札を付けて、ほかの人が動かさないようにします。", "Saya pasti menghentikan mesin dan mematikan daya. Saya memasang tanda \"sedang dikerjakan\" agar orang lain tidak menyalakannya.", [("電源", "daya listrik"), ("札", "tanda/label"), ("止める", "menghentikan")]),
 "anzen-03": ("機械で、指や服が巻き込まれないために、何をしますか。", "Apa yang Anda lakukan agar jari dan pakaian tidak terjerat mesin?", "回っている部分には、手を近づけません。手袋やゆるい服は、使わないときもあります。長い髪は、まとめます。", "Saya tidak mendekatkan tangan ke bagian yang berputar. Kadang sarung tangan dan pakaian longgar tidak dipakai. Rambut panjang saya ikat.", [("巻き込まれる", "terjerat"), ("髪", "rambut"), ("ゆるい", "longgar")]),
 "anzen-04": ("重いものを運ぶとき、どうしますか。", "Apa yang Anda lakukan saat mengangkat barang berat?", "一人で持てないときは、ほかの人に頼みます。腰を曲げないで、ひざを使って持ち上げます。", "Kalau tidak sanggup sendiri, saya minta bantuan orang lain. Saya mengangkat dengan menekuk lutut, bukan membungkuk dari pinggang.", [("腰", "pinggang"), ("ひざ", "lutut"), ("頼む", "meminta bantuan")]),
 "seikatsu-07": ("工場が多い町での生活に、不便なことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan ketidaknyamanan hidup di kota industri?", "大丈夫です。寮から工場までの行き方を、事前に調べます。休みの日は、買い物や勉強をします。", "Tidak masalah. Saya akan mengecek rute dari asrama ke pabrik sebelumnya. Saat libur saya berbelanja dan belajar.", [("寮", "asrama"), ("通勤", "berangkat kerja"), ("調べる", "mengecek")]),
 "seikatsu-08": ("日本のものづくりについて、知っていることはありますか。", "Apa yang Anda ketahui tentang monozukuri (pembuatan barang) Jepang?", "日本の製品は、品質が高くて、長く使えると聞きました。細かいところまで、ていねいに作ることが大切だと思います。", "Saya dengar produk Jepang berkualitas tinggi dan awet. Menurut saya penting membuat dengan teliti sampai detail kecil.", [("ものづくり", "pembuatan barang"), ("品質", "kualitas"), ("ていねい", "teliti")]),
 "mokuhyou-05": ("日本で製造の仕事を学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar manufaktur di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ機械の使い方や、品質を守る考え方を使って、自分の国の工場で働きたいです。", "Saya ingin bekerja di pabrik di negara saya dengan memakai cara pakai mesin dan cara berpikir menjaga kualitas yang saya pelajari di Jepang.", [("機械", "mesin"), ("品質", "kualitas"), ("工場", "pabrik")]),
})
